    """One loader call in flight, shared by its owner and its waiters."""

    __slots__ = ("owner", "done", "value", "error", "has_stale", "stale_value")

    def __init__(self, owner):
        self.owner = owner  # thread ident of the thread running the loader
        self.done = False
        self.value = None
        self.error = None
        self.has_stale = False  # set when the failure is answered with a stale value
        self.stale_value = None


